import{_ as o,o as d,c as a,ag as e}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"天涯神贴合集索引","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/index.md","filePath":"topics/tianya/index.md"}'),n={name:"topics/tianya/index.md"};function s(r,t,i,l,h,u){return d(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="天涯神贴合集索引" tabindex="-1">天涯神贴合集索引 <a class="header-anchor" href="#天涯神贴合集索引" aria-label="Permalink to &quot;天涯神贴合集索引&quot;">​</a></h1><blockquote><p>整理日期：2026-11-06 · 来源：用户自整理精读笔记（<code>notes/</code> 共 11 份，逐字保留）</p></blockquote><blockquote><p>关键词：天涯神贴, 天涯论坛, kkndme, 货币蓄水池, 房价预测, 多空论战, 职业+灵异, 杠杆爆仓, 反诈, 民间史论, 预言命中率, 利益分析法, 蓄水池, 外储, 土地财政</p></blockquote><hr><h2 id="一、这是什么-以及为什么要存下来" tabindex="-1">一、这是什么，以及为什么要存下来 <a class="header-anchor" href="#一、这是什么-以及为什么要存下来" aria-label="Permalink to &quot;一、这是什么，以及为什么要存下来&quot;">​</a></h2><p>一份 <strong>138 帖 / 约 20 万页</strong>的天涯论坛「神贴」合集（2005—2020），用户做了逐帖精读，产出 11 份分类笔记。</p><p><strong>⚠️ 保存状态（这条最重要）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原合集 PDF（138 帖 / 77 MB 提取文本）</span></span>
<span class="line"><span>  └─ 提取到 /tmp/thunder/texts/ ──→ 重启即失，已确认不存在（2026-11-06 核）</span></span>
<span class="line"><span>      └─ 唯一存世副本 = notes/ 下这 11 份精读笔记（176 KB）</span></span></code></pre></div><p>也就是说 <strong><code>notes/</code> 里的内容是这批语料的最终遗存</strong>，不是&quot;顺便抄一份&quot;。原始 PDF 若还在本地某处，应另行备份到冷存储；<code>/tmp</code> 路径绝不能再作为唯一落点。</p><p><strong>这批材料的三重价值：</strong></p><ol><li><strong>预言可检验</strong>——2005—2020 的人做 2026 的预测，检验结果已经出来了，这是一份罕见的、带时间戳的&quot;认知样本库&quot;；</li><li><strong>叙事可解剖</strong>——为什么某些帖子能活十年、被反复考古，配方是可拆解、可迁移的；</li><li><strong>时代切片</strong>——1976 武汉的竹床阵、2010 深圳的十元店、2004 杭州的看房潮，比任何史料都具体。</li></ol><hr><h2 id="二、十卷地图" tabindex="-1">二、十卷地图 <a class="header-anchor" href="#二、十卷地图" aria-label="Permalink to &quot;二、十卷地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>卷</th><th>文件</th><th>内容</th><th>代表帖</th><th>层</th></tr></thead><tbody><tr><td>01</td><td><a href="/zhishiku-reading/topics/tianya/notes/01_KK三部曲与房价终极论战.html">KK三部曲与房价终极论战</a></td><td>房价论战的四个原点文本</td><td>kkndme《三部曲》2010、炒房人《终极预测》2010、北望帝都 2010、孤独的思想 2005</td><td>财经 · 预言</td></tr><tr><td>02</td><td><a href="/zhishiku-reading/topics/tianya/notes/02_房产实战与多空论战.html">房产实战与多空论战</a></td><td>13 篇实战帖，多空双方互砍</td><td>看西山的子房《北京十年房子故事》、海男的故事 2016、房奴十年 2010</td><td>财经 · 实战</td></tr><tr><td>03</td><td><a href="/zhishiku-reading/topics/tianya/notes/03_宏观经济与货币.html">宏观经济与货币</a></td><td>12 文件，货币/外储/银行内部视角</td><td>flp713《冰冷的经济真相》2011、曼因斯坦 2016、螺蛳大少（银行内部人）2011</td><td>财经 · 机制</td></tr><tr><td>04</td><td><a href="/zhishiku-reading/topics/tianya/notes/04_趋势预测合集.html">趋势预测合集</a></td><td>24 篇年度与周期预测</td><td>老仇乱侃（命中率最高）、Kulese、北京毛毛 2006</td><td>财经 · 预言</td></tr><tr><td>05</td><td><a href="/zhishiku-reading/topics/tianya/notes/05_股市交易与币圈.html">股市交易与币圈</a></td><td>10 篇，真金白银换的经验</td><td>南侠1987（两次爆仓）、peterwind（期货&quot;道&quot;）、赌坛老千自述</td><td>交易 · 忏悔录</td></tr><tr><td>06</td><td><a href="/zhishiku-reading/topics/tianya/notes/06_职场社会与骗局.html">职场社会与骗局</a></td><td>13 篇职场 + 反诈</td><td>《惊天骗局：高级招商主管的自白》2007、《中国式骗局大全》、《职业如何规划》</td><td>社会 · 反诈</td></tr><tr><td>07</td><td><a href="/zhishiku-reading/topics/tianya/notes/07_灵异小说名著系.html">灵异小说名著系</a></td><td>14 部长篇</td><td>《宜昌鬼事》蛇从革、《青囊尸衣》鲁班尺、《民调局异闻录》</td><td>叙事 · 架空</td></tr><tr><td>08</td><td><a href="/zhishiku-reading/topics/tianya/notes/08_灵异亲历与悬案.html">灵异亲历与悬案</a></td><td>12 篇第一人称</td><td>天津刑警奇闻录、殡葬业者、091 气象所、1976 江汉阴阳眼</td><td>叙事 · 伪纪实</td></tr><tr><td>09</td><td><a href="/zhishiku-reading/topics/tianya/notes/09_历史军事.html">历史军事</a></td><td>6 部民间史论</td><td>《太平洋战争》青梅煮酒、《正面抗日战场》关河五十州</td><td>史论 · 演义</td></tr><tr><td>10</td><td><a href="/zhishiku-reading/topics/tianya/notes/10_小说杂集与玄学.html">小说杂集与玄学</a></td><td>史论/小说/玄学/商业混装</td><td>《宝钗比黛玉大八岁》（文本细读范本）、《雨夜谈经》、《写在脸上的风水》</td><td>杂</td></tr></tbody></table><p><strong>读法提示：</strong> 01—04 是<strong>同一个问题的四次逼近</strong>（中国房价与货币到底怎么走），论坛用十五年把它们变成了可打分的考试；05—10 是<strong>叙事与经验层</strong>，没有预测，但提供了&quot;配方&quot;样本。</p><hr><h2 id="三、两条主干" tabindex="-1">三、两条主干 <a class="header-anchor" href="#三、两条主干" aria-label="Permalink to &quot;三、两条主干&quot;">​</a></h2><h3 id="主干-a-财经预言层-01—04-约-53-个文本单元" tabindex="-1">主干 A：财经预言层（01—04，约 53 个文本单元） <a class="header-anchor" href="#主干-a-财经预言层-01—04-约-53-个文本单元" aria-label="Permalink to &quot;主干 A：财经预言层（01—04，约 53 个文本单元）&quot;">​</a></h3><p>一句话概括论战结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        房价由什么决定？</span></span>
<span class="line"><span>   ┌────────────┬────────────┬────────────┐</span></span>
<span class="line"><span>   精英收入      财政+货币     人口+流动性</span></span>
<span class="line"><span>  （KK 2010）   （flp713 2011）(海男 2016)</span></span>
<span class="line"><span>       │             │             │</span></span>
<span class="line"><span>       └──── 共同盲点：没人把&quot;政府绝不允许跌&quot;</span></span>
<span class="line"><span>              当成假设，而是当成公理 ────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>                  2021 后集体失效</span></span></code></pre></div><ul><li><strong>共同世界观</strong>：房价不是供需问题，是**财政（土地第二财政）× 货币（超发与蓄水池）× 权力（双轨制与垄断）**的铁三角。</li><li><strong>共同盲点</strong>：全部默认国家信用与货币扩张永续，没人推演&quot;主动去杠杆 + 人口拐点&quot;的组合拳。他们&quot;对&quot;的那十年，养成了读者对确定性的迷信。</li><li><strong>结局校正</strong>：2021 年后普跌，&quot;任何时刻买房都对&quot;成反面教材。留给 2026 年读者的不是点位表，是工具（见下）和一条纪律——<strong>对任何&quot;这一次不一样&quot;的叙事，先写下它的失效条件</strong>。</li></ul><p>预言的分层命中率、逐帖名单与失败模式，见 → <span class="uncollected-link" title="此关联资料尚未收录到阅读站">prediction-ledger.md</span>。</p><h3 id="主干-b-叙事层-05—10" tabindex="-1">主干 B：叙事层（05—10） <a class="header-anchor" href="#主干-b-叙事层-05—10" aria-label="Permalink to &quot;主干 B：叙事层（05—10）&quot;">​</a></h3><p>灵异、爆仓忏悔、骗子自白、民间史论看似无关，<strong>共用同一套信任装置</strong>：亲历型叙事人 + 真实坐标 + 知识密度 + 悬置优于解释。天涯最红的配方是&quot;<strong>职业 + 灵异</strong>&quot;——职业干货是信任状，鬼故事只是糖衣。</p><p>配方解剖、滥用滑坡、以及这套配方在今天的对应物，见 → <a href="/zhishiku-reading/topics/tianya/shengtie-formula.html">shengtie-formula.md</a>。</p><hr><h2 id="四、六件可复用工具-各卷总览提炼" tabindex="-1">四、六件可复用工具（各卷总览提炼） <a class="header-anchor" href="#四、六件可复用工具-各卷总览提炼" aria-label="Permalink to &quot;四、六件可复用工具（各卷总览提炼）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>工具</th><th>出处</th><th>一句话用法</th></tr></thead><tbody><tr><td>1</td><td><strong>利益分析法</strong></td><td>kkndme 01</td><td>&quot;辨别利益是看透一切事物真相的武器&quot;——把政策翻译成「谁受益、谁背锅、谁买单」</td></tr><tr><td>2</td><td><strong>政策—媒体五阶段剧本</strong></td><td>炒房人 01</td><td>揭露暴涨 → 表决心 → 夸成果 → 开发商做秀要挟 → 政府托市；先判断现在第几幕</td></tr><tr><td>3</td><td><strong>读文件倒推十年布局</strong></td><td>flp713 03</td><td>&quot;现在发生的是前 10 年宏观布局决定的&quot;</td></tr><tr><td>4</td><td><strong>拆央行资产负债表</strong></td><td>曼因斯坦 03</td><td>看外汇占款判这次是&quot;放水&quot;还是&quot;救火&quot;；外储是因，资产是果</td></tr><tr><td>5</td><td><strong>换手率/流动性体温计</strong></td><td>海男 46、88</td><td>二手房能否顺利卖掉，比中介和媒体的嗓门诚实得多</td></tr><tr><td>6</td><td><strong>可证伪性打分卡</strong></td><td>04 卷总览</td><td>读任何预言先问：方向/结构/点位分开算分了吗？失效条件写了吗？</td></tr></tbody></table><p><strong>反工具（识别流量生意）：</strong>「准确率 100%」「你该怎么完还是怎么完」式全知口吻 → 越全知越接近流量生意。看荐股/荐房的人先问一句：<strong>他靠什么赚钱？</strong>（02 卷 40 帖卖课建群、05 卷&quot;晒收益=向粉丝收水子&quot;是同一个判据）</p><hr><h2 id="五、交叉关联-与库内主题的接口" tabindex="-1">五、交叉关联（与库内主题的接口） <a class="header-anchor" href="#五、交叉关联-与库内主题的接口" aria-label="Permalink to &quot;五、交叉关联（与库内主题的接口）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关联主题</th><th>连接点</th></tr></thead><tbody><tr><td><code>real-estate/</code></td><td><strong>互补而非重复</strong>：房产主题给的是&quot;当下怎么判断新区&quot;（证据硬度阶梯、判断四问），本主题给的是&quot;十五年前的人怎么判断、错在哪&quot;——同一问题的<strong>前瞻版与复盘版</strong></td></tr><tr><td><code>economic-cycles/</code></td><td>天涯帖是周期理论在<strong>具体时空的落地样本</strong>（土地财政、去杠杆、通缩切换），可与 <code>sme-structural-squeeze</code> 的中小企业挤压互证</td></tr><tr><td><code>mao-zedong/</code>（矛盾论·实践论）</td><td>kkndme 的&quot;利益分析法&quot;是《矛盾论》&quot;主要矛盾&quot;的民用版；e路狂飙&quot;决定报酬的是利用价值&quot;是&quot;没有调查没有发言权&quot;的职场版</td></tr><tr><td><code>investment-methods/</code></td><td>05 卷&quot;杠杆是绞肉机/轻仓是活路&quot;与 <code>most-important-thing</code>、<code>six-story-pagoda-wealth</code> 的风险观同源；&quot;承认自己是屌丝&quot;＝承认能力圈边界</td></tr><tr><td><code>stock-investment/</code></td><td>05 卷赌场篇的&quot;期望值注定为负&quot;是 <code>11k-follower-income</code> 小资金策略的反面教材</td></tr><tr><td><code>career-observation/</code></td><td>06 卷&quot;平台 &gt; 地域 &gt; 努力&quot;&quot;当你只是成本，寒冬第一刀落在你头上&quot;</td></tr><tr><td><code>psychology/</code></td><td>05 卷&quot;损失厌恶——牛市拿不住、熊市装死&quot;；08 卷的&quot;半信半疑是可持续更新的钩子&quot;是注意力心理学</td></tr><tr><td><code>global-finance/</code></td><td>03 卷&quot;霸道木桶理论&quot;（工业/科技/金融/军事/文化五块板）与 04 卷&quot;美国先漏工业&quot;</td></tr><tr><td><code>philosophy/</code>（含认识论）</td><td><strong>最强连接</strong>：00 卷总纲的核心结论——&quot;对任何&#39;这一次不一样&#39;的叙事，先写下失效条件&quot;——就是可证伪性与归纳问题的中文论坛版</td></tr><tr><td><code>philosophy/</code>（罗素《闲散颂》）</td><td>04 卷老仇&quot;承认自己是屌丝&quot;与罗素论&quot;无用知识&quot;同调：<strong>降低对自己禀赋的迷信</strong></td></tr><tr><td><code>biomedicine</code> / <code>neuroscience</code></td><td>07 卷《DNA 鉴定师》《心理大师》的硬知识来源；&quot;知识密度即护城河&quot;</td></tr><tr><td><code>weiqi/</code></td><td>曼因斯坦用&quot;围棋弃大龙&quot;解释 2016 用楼市锁游资保外储——<strong>行业术语跨域借用的典型样本</strong></td></tr><tr><td><code>culture/</code></td><td>09/10 卷的民间史论与红学文本细读，与库内文化类内容同属&quot;非学院的知识生产&quot;</td></tr></tbody></table><hr><h2 id="六、三条阅读路线" tabindex="-1">六、三条阅读路线 <a class="header-anchor" href="#六、三条阅读路线" aria-label="Permalink to &quot;六、三条阅读路线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路线</th><th>顺序</th><th>适合</th></tr></thead><tbody><tr><td><strong>考据路线</strong>（要答案）</td><td>00 → 01 → 03 → <span class="uncollected-link" title="此关联资料尚未收录到阅读站">prediction-ledger</span> → 04</td><td>想知道&quot;他们到底说对没对&quot;、想拿走可检验的判断框架</td></tr><tr><td><strong>手艺路线</strong>（要方法）</td><td>00 → <a href="/zhishiku-reading/topics/tianya/shengtie-formula.html">shengtie-formula</a> → 08 → 06 → 05</td><td>想学&quot;怎么写/怎么读一个能活十年的叙事&quot;</td></tr><tr><td><strong>时代路线</strong>（要见闻）</td><td>08（1976/1985/2010）→ 02（房奴十年）→ 06（泰国物价考古）→ 09</td><td>想通过具体的人看具体年代</td></tr></tbody></table><hr><h2 id="七、使用纪律-⚠️-别拿它当史料" tabindex="-1">七、使用纪律（⚠️ 别拿它当史料） <a class="header-anchor" href="#七、使用纪律-⚠️-别拿它当史料" aria-label="Permalink to &quot;七、使用纪律（⚠️ 别拿它当史料）&quot;">​</a></h2><ol><li><strong>三分层存放</strong>：<code>notes/</code> 是<strong>二手精读</strong>（用户整理），不是原文；引用时须注明&quot;据天涯帖精读笔记&quot;。</li><li><strong>07—10 卷是文学</strong>：灵异&quot;亲历&quot;多数经不起核验，08 卷笔记已自己标出滑坡（真警察 → 亲历口吻 → 拿&quot;职业&quot;当小说皮）。<strong>当叙事读，不当事实读。</strong></li><li><strong>09 卷史论</strong>：史源单一（多为将领回忆录）、有翻案冲动，&quot;明牌的演义&quot;比冒充定论的写作更可信——用它要分清<strong>演义 / 证词 / 考据</strong>三层。</li><li><strong>预言已过期</strong>：01—04 的任何点位（北京 8 万、上证 1900—2100、纳指 8500）都是<strong>认知样本</strong>，不是操作依据。</li><li><strong>玄学帖的特别标注</strong>：04 卷有 4 篇玄学预测（火运、庚子大劫等），时点命中率反超部分技术派，但<strong>五行外壳无法证伪、无法修正</strong>——笔记的处理方式是&quot;记下命中、存疑方法&quot;，沿用即可。</li></ol><hr><p><em>核心原则：<strong>这批材料的价值不在答案，在失误——它们把&quot;一次都没被检验过的宏论&quot;变成了可打分的考试，而 2026 年的分数已经出来了。</strong></em></p><h2 id="待深化方向" tabindex="-1">待深化方向 <a class="header-anchor" href="#待深化方向" aria-label="Permalink to &quot;待深化方向&quot;">​</a></h2><ul><li>[ ] 若原始 PDF 仍在本地，找出并冷备份（<code>notes/</code> 是唯一副本，单点）</li><li>[ ] 为 01/03 卷的高频论证做&quot;关键数据核实&quot;抽检（如&quot;1 亿劳动人口需 8000 万岗位&quot;&quot;劳动供养率 1:1.1&quot;的出处）</li><li>[ ] 把 <span class="uncollected-link" title="此关联资料尚未收录到阅读站">prediction-ledger</span> 的打分卡用在一篇<strong>今天的</strong>预言上（试跑 ai-system-architecture 里的 AI 主张）</li></ul>`,42)])])}const g=o(n,[["render",s]]);export{p as __pageData,g as default};
